class Solution {
  public String smallestBeautifulString(String s, int k) {
    char[] a = s.toCharArray();
    int n = a.length;
    for (int i = n - 1; i >= 0; i--) {
      for (char c = (char) (a[i] + 1); c < 'a' + k; c++) {
        if (i >= 1 && c == a[i - 1]) continue;
        if (i >= 2 && c == a[i - 2]) continue;
        a[i] = c;
        // k >= 4, so one of 'a'..'c' always differs from the previous two letters
        for (int j = i + 1; j < n; j++) {
          char d = 'a';
          while ((j >= 1 && d == a[j - 1]) || (j >= 2 && d == a[j - 2])) d++;
          a[j] = d;
        }
        return new String(a);
      }
    }
    return "";
  }
}
